 const observationIds=new Set(parts.filter(p=>p.type==='probe').map(p=>p.id)),observations=value.observations===undefined?createObservations(parts):entries(value.observations,observationIds,s=>{check(s&&typeof s.enabled==='boolean'&&['day','night'].every(k=>Number.isFinite(s[k])&&s[k]>=0&&s[k]<=1e12));if(s.sites!==undefined){check(s.sites&&typeof s.sites==='object'&&!Array.isArray(s.sites));for(const [id,data]of Object.entries(s.sites)){check(id!==DELIVERY_SITE.id&&!!deliverySite(id)&&data&&['day','night'].every(k=>Number.isFinite(data[k])&&data[k]>=0&&data[k]<=1e12));copyObservationQuality(data.quality,data);}}const quality=copyObservationQuality(s.quality,s);return {enabled:s.enabled,day:s.day,night:s.night,...(quality?{quality}:{}),...(s.sites?{sites:structuredClone(s.sites)}:{})};});check(observations.size===observationIds.size);
 const batteryIds=new Set(parts.filter(p=>PARTS[p.type].battery).map(p=>p.id)),charge=value.charge===undefined?createCharge(parts):entries(value.charge,batteryIds,(v,id)=>{check(Number.isFinite(v)&&v>=0&&v<=PARTS[byId.get(id).type].battery);return v;});check(charge.size===batteryIds.size);const maneuver=validateManeuverNode(value.maneuver),transferGuide=validateTransferGuide(value.transferGuide);check(value.sasMode!=='maneuver'||maneuver!==null);
